  @protected
  void sse_encode_imaging_event(ImagingEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case ImagingEvent_ExposureStarted(
        durationSecs: final durationSecs,
        frameType: final frameType,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_f_64(durationSecs, serializer);
        sse_encode_frame_type(frameType, serializer);
      case ImagingEvent_ExposureStartedWithFrame(
        durationSecs: final durationSecs,
        frameType: final frameType,
        frameNumber: final frameNumber,
        totalFrames: final totalFrames,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_f_64(durationSecs, serializer);
        sse_encode_frame_type(frameType, serializer);
        sse_encode_u_32(frameNumber, serializer);
        sse_encode_opt_box_autoadd_u_32(totalFrames, serializer);
      case ImagingEvent_ExposureProgress(
        progress: final progress,
        remainingSecs: final remainingSecs,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_f_64(progress, serializer);
        sse_encode_f_64(remainingSecs, serializer);
      case ImagingEvent_ExposureCompleted(
        filePath: final filePath,
        hfr: final hfr,
        starsDetected: final starsDetected,
      ):
        sse_encode_i_32(3, serializer);
        sse_encode_opt_String(filePath, serializer);
        sse_encode_f_64(hfr, serializer);
        sse_encode_u_32(starsDetected, serializer);
      case ImagingEvent_ExposureCompletedWithFrame(
        frameNumber: final frameNumber,
        totalFrames: final totalFrames,
        hfr: final hfr,
        starsDetected: final starsDetected,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_u_32(frameNumber, serializer);
        sse_encode_opt_box_autoadd_u_32(totalFrames, serializer);
        sse_encode_f_64(hfr, serializer);
        sse_encode_u_32(starsDetected, serializer);
      case ImagingEvent_ExposureFailed(error: final error):
        sse_encode_i_32(5, serializer);
        sse_encode_String(error, serializer);
      case ImagingEvent_ExposureCancelled():
        sse_encode_i_32(6, serializer);
      case ImagingEvent_DownloadStarted():
        sse_encode_i_32(7, serializer);
      case ImagingEvent_DownloadCompleted():
        sse_encode_i_32(8, serializer);
      case ImagingEvent_ImageReady(width: final width, height: final height):
        sse_encode_i_32(9, serializer);
        sse_encode_u_32(width, serializer);
        sse_encode_u_32(height, serializer);
      case ImagingEvent_ImageSaved(filePath: final filePath):
        sse_encode_i_32(10, serializer);
        sse_encode_String(filePath, serializer);
      case ImagingEvent_IntegrationProgress(
        phase: final phase,
        fraction: final fraction,
        framesDone: final framesDone,
        framesTotal: final framesTotal,
      ):
        sse_encode_i_32(11, serializer);
        sse_encode_String(phase, serializer);
        sse_encode_f_32(fraction, serializer);
        sse_encode_opt_box_autoadd_u_32(framesDone, serializer);
        sse_encode_opt_box_autoadd_u_32(framesTotal, serializer);
      case ImagingEvent_TemperatureChanged(
        tempCelsius: final tempCelsius,
        coolerPower: final coolerPower,
      ):
        sse_encode_i_32(12, serializer);
        sse_encode_f_64(tempCelsius, serializer);
        sse_encode_f_64(coolerPower, serializer);
      case ImagingEvent_ExposureComplete(success: final success):
        sse_encode_i_32(13, serializer);
        sse_encode_bool(success, serializer);
      case ImagingEvent_ExposureFailedOld(reason: final reason):
        sse_encode_i_32(14, serializer);
        sse_encode_String(reason, serializer);
    }
  }

