  @protected
  void sse_encode_system_event(SystemEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case SystemEvent_Initialized():
        sse_encode_i_32(0, serializer);
      case SystemEvent_ShuttingDown():
        sse_encode_i_32(1, serializer);
      case SystemEvent_Error(message: final message):
        sse_encode_i_32(2, serializer);
        sse_encode_String(message, serializer);
      case SystemEvent_DiskSpaceLow(availableGb: final availableGb):
        sse_encode_i_32(3, serializer);
        sse_encode_f_64(availableGb, serializer);
      case SystemEvent_Notification(
        title: final title,
        message: final message,
        level: final level,
        explicitTransports: final explicitTransports,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(title, serializer);
        sse_encode_String(message, serializer);
        sse_encode_String(level, serializer);
        sse_encode_opt_list_String(explicitTransports, serializer);
      case SystemEvent_EventsDropped(
        droppedCount: final droppedCount,
        totalDropped: final totalDropped,
      ):
        sse_encode_i_32(5, serializer);
        sse_encode_u_64(droppedCount, serializer);
        sse_encode_u_64(totalDropped, serializer);
    }
  }

